using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Reflection;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Geometry;
using Autodesk.AutoCAD.Colors;
using Autodesk.AutoCAD.Runtime;
using MedGas2024.Core;
using MedGas2024.Engine;
[assembly:CommandClass(typeof(BatchRuntimeTests))]
public static class BatchRuntimeTests
{
    static List<string> log=new List<string>();static void Check(bool value,string text){if(!value)throw new System.Exception(text);log.Add("PASS: "+text);}
    static bool Reject(Action a){try{a();return false;}catch(InvalidOperationException){return true;}}
    static DrawingLayerInfo Row(Database db,string name){return DrawingService.Read(db).Single(r=>r.LayerName==name);}
    static ObjectId Layer(Database db,string name,ObjectId type,bool locked=false){using(var tr=db.TransactionManager.StartTransaction()){var table=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForWrite);var layer=new LayerTableRecord{Name=name,LinetypeObjectId=type,Color=Color.FromColorIndex(ColorMethod.ByAci,3),IsLocked=locked};table.Add(layer);tr.AddNewlyCreatedDBObject(layer,true);tr.Commit();return layer.ObjectId;}}
    static ObjectId Pipe(Database db,ObjectId layer,ObjectId type,bool direct=true,ObjectId owner=default(ObjectId))
    {
        using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var space=(BlockTableRecord)tr.GetObject(owner.IsNull?bt[BlockTableRecord.ModelSpace]:owner,OpenMode.ForWrite);var p=new Polyline();p.SetDatabaseDefaults(db);p.AddVertexAt(0,new Point2d(10,20),.2,10,15);p.AddVertexAt(1,new Point2d(110,20),0,15,20);space.AppendEntity(p);tr.AddNewlyCreatedDBObject(p,true);p.LayerId=layer;p.LinetypeId=direct?type:db.ByLayerLinetype;p.Color=Color.FromRgb(10,20,30);p.LinetypeScale=.1;p.Plinegen=false;tr.Commit();return p.ObjectId;}
    }
    static string Geometry(Database db,ObjectId id){using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var p=(Polyline)tr.GetObject(id,OpenMode.ForRead);return p.LayerId.Handle+"|"+p.GetPoint3dAt(0)+"|"+p.GetPoint3dAt(1)+"|"+p.GetBulgeAt(0)+"|"+p.LinetypeScale+"|"+p.Plinegen+"|"+ScaleService.WidthState(p,tr);}}
    static string Symbols(Database db){using(var tr=db.TransactionManager.StartOpenCloseTransaction()){return String.Join(";",((LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForRead)).Cast<ObjectId>().Select(id=>((LayerTableRecord)tr.GetObject(id,OpenMode.ForRead)).Name).OrderBy(x=>x))+"|"+((LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForRead)).Cast<ObjectId>().Count()+"|"+((TextStyleTable)tr.GetObject(db.TextStyleTableId,OpenMode.ForRead)).Cast<ObjectId>().Count();}}
    [CommandMethod("MRTBATCHTEST",CommandFlags.Modal)]public static void Run()
    {
        log.Clear();var previous=HostApplicationServices.WorkingDatabase;string root=Directory.GetParent(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location)).FullName;
        try
        {
            using(var db=new Database(true,true))
            {
                HostApplicationServices.WorkingDatabase=db;ObjectId style,type;
                using(var tr=db.TransactionManager.StartTransaction()){var styles=(TextStyleTable)tr.GetObject(db.TextStyleTableId,OpenMode.ForWrite);var st=new TextStyleTableRecord{Name="BATCH_SOURCE_STYLE",FileName="arial.ttf",TextSize=0,XScale=1};styles.Add(st);tr.AddNewlyCreatedDBObject(st,true);style=st.ObjectId;var types=(LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForWrite);var lt=new LinetypeTableRecord{Name="BATCH_SHARED_TYPE",Comments="original description",NumDashes=3,PatternLength=40};types.Add(lt);tr.AddNewlyCreatedDBObject(lt,true);type=lt.ObjectId;lt.SetDashLengthAt(0,20);lt.SetDashLengthAt(1,-10);lt.SetDashLengthAt(2,-10);lt.SetShapeStyleAt(1,style);lt.SetTextAt(1,"D110.CN");lt.SetShapeScaleAt(1,2.5);lt.SetShapeOffsetAt(1,new Vector2d(-4,-1));tr.Commit();}
                ObjectId a=Layer(db,"MRG_CN_D110_RAW",type),b=Layer(db,"Mr.T_TN_D160_RAW",type),outside=Layer(db,"OUTSIDE",type),empty=Layer(db,"Mr.T_EMPTY_D25_BASE",type),locked=Layer(db,"Mr.T_LOCK_D25_BASE",type,true);
                ObjectId direct=Pipe(db,a,type),bylayer=Pipe(db,a,type,false),other=Pipe(db,outside,type),bp=Pipe(db,b,type);ObjectId block;using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForWrite);var record=new BlockTableRecord{Name="BATCH_NESTED"};bt.Add(record);tr.AddNewlyCreatedDBObject(record,true);block=record.ObjectId;tr.Commit();}ObjectId nested=Pipe(db,a,type,true,block);
                string geo=Geometry(db,direct),nestedGeo=Geometry(db,nested),otherGeo=Geometry(db,other);var color=new BatchEdit{ChangeColor=true,Aci=201};var first=Row(db,"MRG_CN_D110_RAW");string symbols=Symbols(db);var colorPlan=BatchService.Inspect(db,new[]{first},color);Check(colorPlan.CanApply&&!colorPlan.Items[0].Clone&&Symbols(db)==symbols,"Color-only preview does not write or clone definitions");BatchService.Apply(db,colorPlan,color);
                using(var tr=db.TransactionManager.StartOpenCloseTransaction()){Check(((LayerTableRecord)tr.GetObject(a,OpenMode.ForRead)).Color.ColorIndex==201,"Selected layer receives the chosen ACI");Check(((Entity)tr.GetObject(direct,OpenMode.ForRead)).Color.Red==10&&((LayerTableRecord)tr.GetObject(outside,OpenMode.ForRead)).Color.ColorIndex==3,"RGB overrides and outside layer colors remain untouched by default");Check(((LayerTableRecord)tr.GetObject(a,OpenMode.ForRead)).LinetypeObjectId==type,"Color-only edit retains the exact native linetype ID");}
                var change=new BatchEdit{ChangePrefix=true,Prefix="Mr.T",ChangeSuffix=true,Suffix="EST",ChangeLabel=true,Label="HDPE",ForceR=true};var plan=BatchService.Inspect(db,new[]{Row(db,"MRG_CN_D110_RAW"),Row(db,"Mr.T_TN_D160_RAW")},change);Check(plan.CanApply&&plan.Items.Select(x=>x.Preview.TextAfter).SequenceEqual(new[]{"D110.HDPE","D160.HDPE"}),"Real CAD preview preserves row-specific diameters during bulk label changes");Check(plan.Items.All(x=>x.Before==10&&x.After==10),"Unchecked spacing fields preserve each original gap during label edits");BatchService.Apply(db,plan,change);
                ObjectId typeA,typeB;using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var la=(LayerTableRecord)tr.GetObject(a,OpenMode.ForRead);var lb=(LayerTableRecord)tr.GetObject(b,OpenMode.ForRead);typeA=la.LinetypeObjectId;typeB=lb.LinetypeObjectId;Check(la.Name=="Mr.T_CN_D110_EST"&&lb.Name=="Mr.T_TN_D160_EST","Layer renaming preserves native LayerIds");Check(typeA!=type&&typeB!=type&&typeA!=typeB,"Selected layers receive isolated linetypes instead of modifying the shared source");Check(((LinetypeTableRecord)tr.GetObject(type,OpenMode.ForRead)).TextAt(1)=="D110.CN"&&((LinetypeTableRecord)tr.GetObject(typeA,OpenMode.ForRead)).TextAt(1)=="D110.HDPE","Original shared text is unchanged and selected private text is updated");Check(((Entity)tr.GetObject(direct,OpenMode.ForRead)).LinetypeId==typeA&&((Entity)tr.GetObject(bylayer,OpenMode.ForRead)).LinetypeId==db.ByLayerLinetype,"Matching direct old overrides are rebound while ByLayer remains ByLayer");Check(((Entity)tr.GetObject(other,OpenMode.ForRead)).LinetypeId==type&&((Entity)tr.GetObject(nested,OpenMode.ForRead)).LinetypeId==type,"Other layers and nested explicit overrides are not rebound");}
                Check(Geometry(db,direct)==geo&&Geometry(db,nested)==nestedGeo&&Geometry(db,other)==otherGeo,"LayerId, vertex/bulge, variable widths, entity scale and generation flags are preserved");
                var fontEdit=new BatchEdit{ChangeFont=true,FontFile="arial.ttf",Bold=true};var fontPlan=BatchService.Inspect(db,new[]{Row(db,"Mr.T_CN_D110_EST")},fontEdit);Check(fontPlan.CanApply&&fontPlan.Items[0].Height==2.5,"Font-only preview retains source text height");BatchService.Apply(db,fontPlan,fontEdit);using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var newType=(LinetypeTableRecord)tr.GetObject(((LayerTableRecord)tr.GetObject(a,OpenMode.ForRead)).LinetypeObjectId,OpenMode.ForRead);var newStyle=(TextStyleTableRecord)tr.GetObject(newType.ShapeStyleAt(1),OpenMode.ForRead);Check(newType.ShapeStyleAt(1)!=style&&newStyle.Font.Bold&&!((TextStyleTableRecord)tr.GetObject(style,OpenMode.ForRead)).Font.Bold,"Bold font is isolated in a new style and never changes the shared source style");}
                var normalize=new BatchEdit{ColorByLayer=true};BatchService.Apply(db,BatchService.Inspect(db,new[]{Row(db,"Mr.T_CN_D110_EST")},normalize),normalize);using(var tr=db.TransactionManager.StartOpenCloseTransaction()){Check(((Entity)tr.GetObject(direct,OpenMode.ForRead)).Color.ColorMethod==ColorMethod.ByLayer&&((Entity)tr.GetObject(nested,OpenMode.ForRead)).Color.Red==10,"Explicit color normalization affects direct curves only");}
                var rollback=new BatchEdit{ChangePrefix=true,Prefix="Office",ChangeDescription=true,DescriptionTemplate="{System} D{D}"};var stable=Symbols(db);var failed=BatchService.Inspect(db,new[]{Row(db,"Mr.T_CN_D110_EST"),Row(db,"Mr.T_TN_D160_EST")},rollback);Check(Reject(()=>BatchService.Apply(db,failed,rollback,true))&&Symbols(db)==stable,"Mid-batch failure rolls back renames and all newly cloned definitions");
                var stale=BatchService.Inspect(db,new[]{Row(db,"Mr.T_CN_D110_EST")},color);using(var tr=db.TransactionManager.StartTransaction()){((Entity)tr.GetObject(direct,OpenMode.ForWrite)).Color=Color.FromRgb(50,60,70);tr.Commit();}Check(Reject(()=>BatchService.Apply(db,stale,color)),"Changed entity overrides invalidate an already reviewed plan");
                ObjectId hidden=Layer(db,"Mr.T_HIDDEN_D25_BASE",type);using(var tr=db.TransactionManager.StartTransaction()){var hiddenLayer=(LayerTableRecord)tr.GetObject(hidden,OpenMode.ForWrite);hiddenLayer.IsOff=true;hiddenLayer.IsFrozen=true;tr.Commit();}var hiddenPlan=BatchService.Inspect(db,new[]{Row(db,"Mr.T_HIDDEN_D25_BASE")},color);Check(hiddenPlan.CanApply,"Off/frozen layers can have metadata edited without being thawed");BatchService.Apply(db,hiddenPlan,color);using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var hiddenLayer=(LayerTableRecord)tr.GetObject(hidden,OpenMode.ForRead);Check(hiddenLayer.IsOff&&hiddenLayer.IsFrozen&&hiddenLayer.Color.ColorIndex==201,"Bulk metadata edits retain off/frozen visibility state");}
                var deletion=new BatchEdit{Delete=true};Check(!BatchService.Inspect(db,new[]{Row(db,"Mr.T_CN_D110_EST")},deletion).CanApply,"Used layer cannot be deleted even when selected explicitly");Check(!BatchService.Inspect(db,new[]{Row(db,"Mr.T_LOCK_D25_BASE")},color).CanApply,"Locked layer prevents mutation before any write");Check(!BatchService.Inspect(db,new[]{Row(db,"0")},deletion).CanApply,"Protected/current layer cannot be deleted");
                var collision=new BatchEdit{ExactLayer=true,LayerName="OUTSIDE"};Check(!BatchService.Inspect(db,new[]{Row(db,"Mr.T_CN_D110_EST")},collision).CanApply,"Existing target layer name blocks the plan without merging objects");
                var assign=new BatchEdit{ChangeLinetype=true,AssignLinetype="BATCH_SHARED_TYPE",RebindOldOverrides=false};BatchService.Apply(db,BatchService.Inspect(db,new[]{Row(db,"Mr.T_TN_D160_EST")},assign),assign);using(var tr=db.TransactionManager.StartOpenCloseTransaction()){Check(((LayerTableRecord)tr.GetObject(b,OpenMode.ForRead)).LinetypeObjectId==type&&((Entity)tr.GetObject(bp,OpenMode.ForRead)).LinetypeId==typeB,"Choosing an existing linetype can preserve entity-specific overrides explicitly");}
                var remove=BatchService.Inspect(db,new[]{Row(db,"Mr.T_EMPTY_D25_BASE")},deletion);Check(remove.CanApply,"Unreferenced empty layer is eligible after native Purge validation");BatchService.Apply(db,remove,deletion);Check(empty.IsErased&&!type.IsErased&&!style.IsErased,"Deletion removes only the empty layer, retaining linetype and style records");
            }log.Add("RESULT: PASS; scratch Database only. Active user drawing was not edited.");
        }
        catch(System.Exception ex){log.Add("RESULT: FAIL");log.Add(ex.ToString());}
        finally{HostApplicationServices.WorkingDatabase=previous;File.WriteAllLines(Path.Combine(root,"evidence","batch-runtime-tests.txt"),log);var doc=Autodesk.AutoCAD.ApplicationServices.Core.Application.DocumentManager.MdiActiveDocument;if(doc!=null)doc.Editor.WriteMessage("\n"+String.Join("\n",log)+"\n");}
    }
}
